verus! {

fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64>
    recommends
        // matrix has at least one row
        choices.len() > 0,
        // every row length == indices length
        forall(|r: usize| r < choices.len() ==> choices[r].len() == indices.len()),
        // every index value is a valid row selector
        forall(|i: usize| i < indices.len() ==> (indices[i] as usize) < choices.len()),
    ensures
        // result length == indices length
        |result: Vec<f64>| result.len() == indices.len() &&
        // for each position i: result[i] == choices[indices[i]][i]
        forall(|i: usize| i < indices.len() ==> result[i] == choices[indices[i] as usize][i]),
{
    let n = indices.len();

    // create a mutable vector for results, uninitialized length n
    let mut result: Vec<f64> = Vec::new();
    result.reserve(n);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            // result length always equals current i
            result.len() == i,
        decreases n - i,
    {
        // safe indexing because of preconditions:
        //  - i < n
        //  - indices[i] < choices.len()
        let row = indices[i] as usize;
        let val = choices[row][i];
        result.push(val);

        i += 1;
    }

    result
}
}